macroData.command:
const version = "13.0.58";
try {
  if (args[0].tag === "OnUse" && args[0].macroPass === "postActiveEffects") {
    const monksFocus = actor.items.find(i => i.system.identifier === "monks-focus");
    if (!monksFocus) {
      ui.notifications.warn("No Monk's Focus feature found on this actor.");
      return;
    }
    const dieFormula = actor.system.scale?.monk?.die;
    if (!dieFormula) {
      ui.notifications.warn("No Martial Arts die found — is this character a Monk?");
      return;
    }
    const roll = await new Roll(dieFormula.formula ?? dieFormula.toString()).evaluate();
    await roll.toMessage({
      speaker: ChatMessage.getSpeaker({ actor }),
      flavor: `${macroItem.name} — Martial Arts die (Focus Points regained)`
    });
    const maxUses = monksFocus.system.uses.max;
    const resolvedMax = typeof maxUses === "string" ? Roll.safeEval(Roll.replaceFormulaData(maxUses, actor.getRollData())) : maxUses;
    const currentSpent = monksFocus.system.uses.spent;
    const regained = Math.min(roll.total, currentSpent);
    if (regained > 0) {
      await monksFocus.update({ "system.uses.spent": currentSpent - regained });
      ChatMessage.create({
        content: `<p><strong>${actor.name}</strong> regains <strong>${regained}</strong> Focus Point${regained !== 1 ? "s" : ""} (${monksFocus.system.uses.spent - regained}/${resolvedMax} spent).</p>`,
        speaker: ChatMessage.getSpeaker({ actor })
      });
    } else {
      ChatMessage.create({
        content: `<p><strong>${actor.name}</strong> has no spent Focus Points to regain.</p>`,
        speaker: ChatMessage.getSpeaker({ actor })
      });
    }
  }
} catch (err) {
  console.error(`Dragonhide Belt ${version}`, err);
}
